WITH flattened_attrs AS (SELECT id, tier_prices, discounts, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT id, lowest_price, AVG(lowest_price) OVER (ORDER BY avg_tier_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_lowest_price, SUM(lowest_price) OVER (ORDER BY avg_tier_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_lowest_price, MIN(lowest_price) OVER (ORDER BY avg_tier_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_lowest_price, FIRST_VALUE(avg_tier_price) IGNORE NULLS OVER (ORDER BY lowest_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_avg_tier_price FROM flattened_attrs WHERE avg_tier_price < 17
